	zip.Describe("github.com/hanzoai/cloud/apps/agents GET /v1/agent/builds", zip.Doc{
		Description: "Returns the public index of every published build, most recently\nupdated first, so a gallery can link straight to the story behind each product.\nPUBLIC, no tenancy: publishing is the author's act, and only published root\nsessions appear here.",
		Fields: map[string]string{
			"buildList.builds":       "Builds is every published build, most recently updated first.",
			"buildSummary.agent":     "Agent is the label the surface that did the work calls itself by.",
			"buildSummary.endedAt":   "EndedAt is when it finished, same format. Empty means it is still going.",
			"buildSummary.org":       "Org and Project are the build's public ADDRESS — the pair the full story is\nread at, and the pair a visitor sees in the URL bar. Not a tenant key: this\nindex is anonymous and lists only what authors published.",
			"buildSummary.project":   "Project is the product's slug, the second half of that address.",
			"buildSummary.repo":      "Repo is the repository the work was done in, as the session reported it.",
			"buildSummary.session":   "Session is the agent session behind the build, and the value its commits name\nin their `Hanzo-Session:` trailer.",
			"buildSummary.startedAt": "StartedAt is when the session opened, RFC 3339 in UTC.",
			"buildSummary.status":    "Status is the session's own: running, paused, done or error — so a card can\nshow a build still being written.",
			"buildSummary.title":     "Title is the human line for the card. Sent even when empty, like every field\nhere, because that is what this route has always sent.",
			"buildSummary.turns":     "Turns is HOW MANY turns the transcript holds — a COUNT, unlike the `turn` on\neach turn of the full story, which is that turn's position. The full read\nreturns at most 1000 of them; this number is not capped.",
			"buildsQuery.limit":      "Limit caps the page. Absent, zero or over 500 reads as 100.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents GET /v1/agent/builds/:org/:project", zip.Doc{
		Description: "Returns the readable build of one product: the agent session that\nproduced it, turn by turn — the prompts, the reasoning, the commits each turn\nproduced — plus the exact `git log` that re-derives every commit binding from\ngit itself, so nothing here has to be taken on trust.\n\nPUBLIC, no tenancy: it answers only for a session its author explicitly\npublished, which is what makes it safe to be anonymous. An unpublished session\nis invisible here no matter who asks; its owner reads it through the org-scoped\n/v1/agent/sessions routes, which need a validated principal.",
		Fields: map[string]string{
			"buildRef.org":        "Org is the org that published the build, from the path.",
			"buildRef.project":    "Project is the product's slug, from the path.",
			"buildTurn.actor":     "Actor is who took the turn. A deploy turn's actor is the literal \"deploy\",\nbecause nobody took it.",
			"buildTurn.at":        "At is when the turn was recorded, RFC 3339 in UTC to the second.",
			"buildTurn.body":      "Body is the readable text of the turn, taken from the stored event's `text`.\nEmpty when the event carried a payload of some other shape — this route reads\ntranscripts and does not invent prose for turns that are not one.",
			"buildTurn.commit":    "Commit is the full sha this turn produced, empty when the turn changed\nnothing. It is ECHOED from the transcript, and the authority is the commit\nitself: it carries the `Hanzo-Session:`/`Hanzo-Turn:` trailer, or a note under\nrefs/notes/hanzo-provenance saying the same, so the claim is checkable at\nsource with the command in `verify`.",
			"buildTurn.kind":      "Kind is what the turn was, from the log's closed six: message, tool-call,\nspawn, log, status, control. A deploy arrives as a `status` turn.",
			"buildTurn.subject":   "Subject is that commit's subject line, from the same transcript, so a reader\nsees what the commit says without fetching the repository.",
			"buildTurn.turn":      "Seq is this turn's POSITION in the session's log — monotonic from 1, per\nsession — and it is what a commit's `Hanzo-Turn:` trailer names. It is not a\ncount of anything: the count is `turns` on the summary beside it.",
			"buildView.agent":     "Agent is the label the surface that did the work calls itself by.",
			"buildView.endedAt":   "EndedAt is when it finished, same format. Empty means it has not — the build\nis still going.",
			"buildView.model":     "Model is the model that did the work, taken from the FIRST turn whose body\nnames one — a transcript states it, this route does not resolve it. Empty when\nno turn said.",
			"buildView.org":       "Org is the org that published this build, echoed from the URL. It is part of\nthe build's public ADDRESS and not a tenant key — this route is anonymous, and\nthe only rows it can reach are ones an author explicitly published.",
			"buildView.project":   "Project is the product's slug, the other half of that address.",
			"buildView.repo":      "Repo is the repository the work was done in, as the session reported it.",
			"buildView.session":   "Session is the id of the agent session this story IS — the same value a\nproduced commit carries in its `Hanzo-Session:` trailer, which is what ties\nthe repository's history to this page.",
			"buildView.startedAt": "StartedAt is when the session opened, RFC 3339 in UTC.",
			"buildView.status":    "Status is the session's own: running, paused, done or error. A build can be\nread while it is still being written, so this is not always terminal — and an\n`error` build is still a readable story, not a missing page.",
			"buildView.title":     "Title is the human line the session was opened or renamed with. Empty when\nnobody gave it one.",
			"buildView.turns":     "Turns is the whole transcript, oldest first, capped at 1000: a published build\nis a story to read down, not an archive to page.",
			"buildView.verify":    "Verify is the exact command that re-derives every commit binding below\nstraight from git, so nothing here has to be taken on trust.",
		},
		Example: json.RawMessage(`{"org":"hanzo","project":"landing"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents GET /v1/agent/groups", zip.Doc{
		Description: "Returns every Bot Group defined in the caller's org, ordered\nfrom Layer 1 downward.",
		Fields: map[string]string{
			"groupList.groups":              "Groups is the org's Bot Groups ordered by layer ascending, then name.",
			"groupPolicy.alpha":             "Alpha is the supermajority quorum fraction in (0, 1] required for a round to\nlock on a candidate proposal (defaults to 0.67, i.e. 2/3, for quasar).",
			"groupPolicy.beta":              "Beta is the number of consecutive quorum rounds required to finalize a Lux\nQuasar certificate (defaults to 2).",
			"groupPolicy.confidenceFloor":   "ConfidenceFloor is the minimum self-reported confidence in [0, 1] required by\nthe kai policy before accepting a consensus answer without escalation.",
			"groupPolicy.customRule":        "CustomRule holds the natural-language adjudication rubric applied when kind\nis custom.",
			"groupPolicy.escalateToPrimary": "EscalateToPrimary forwards deadlocked or low-confidence ballots to the org's\nPrimary Bot (\"hanzo\") for tie-breaking finality.",
			"groupPolicy.kind":              "Kind selects the coordination mechanism: leader, quasar, majority, weighted,\nunanimous, kai, or custom.",
			"groupPolicy.leader":            "Leader names the bot that decomposes tasks and synthesizes member outputs\nwhen kind is leader (or adjudicates when kind is custom).",
			"groupPolicy.maxBudgetMicroUSD": "MaxBudgetMicroUSD caps the combined spend of a single group run in integer\nmicro-USD when positive.",
			"groupPolicy.quasarProfile":     "QuasarProfile selects a Lux Quasar preset (polaris, aurora, or pulsar) when\nkind is quasar. Explicit sampleK, alpha, and beta values override the preset.",
			"groupPolicy.sampleK":           "SampleK caps how many group members are sampled per consensus round (for\nexample 3 for polaris, 5 for aurora, 7 for pulsar). Zero samples all members.",
			"groupPolicy.weights":           "Weights optionally overrides per-member voting weights for weighted and\nquasar policies; unlisted members default to weight 1.0.",
			"groupView.createdAt":           "CreatedAt is when the group was created, RFC 3339 UTC.",
			"groupView.description":         "Description summarizes what the group owns so Primary Bot \"hanzo\" and parent\nlayers know when to delegate to it.",
			"groupView.id":                  "ID is the group's stable server-minted handle (\"grp_\" + hex).",
			"groupView.layer":               "Layer is the hierarchy tier (1 = direct report to Primary Bot \"hanzo\", 2+ =\nnested sub-groups and specialist pools).",
			"groupView.members":             "Members lists the bot names belonging to this group in deterministic order.",
			"groupView.name":                "Name is the group's org-unique handle, addressable as group_<name> in tools\nand transport routing.",
			"groupView.parentGroupId":       "ParentGroupID names the parent Bot Group (\"grp_...\") when this group sits at\nLayer 2 or deeper; empty means it reports directly to Primary Bot \"hanzo\".",
			"groupView.policy":              "Policy defines the leader, Lux Quasar, or voting consensus rules for this\ngroup.",
			"groupView.updatedAt":           "UpdatedAt is when the group definition was last updated, RFC 3339 UTC.",
			"groupWeight.agent":             "Agent is the member bot's org-unique name or public agent_... id.",
			"groupWeight.weight":            "Weight is the non-negative voting multiplier assigned to this member (1.0 is\nstandard parity).",
		},
	})
