	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent", zip.Doc{
		Description: "Defines an agent in the caller's org: a model, a system prompt\n(instructions) and a set of tool names. The name must be unique in the org and\nmatch ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$. An omitted model takes the\ndeployment's configured default; a named one is checked against the gateway's\nserved catalog, so a model this deployment never serves is refused here rather\nthan failing at run time. A long-running agent must carry a 5-field cron\nschedule (the scheduler would otherwise never fire it) and counts against a\nper-org cap on scheduled agents. An agent spawned by another names it as its\nparent; the parent must be an agent of the caller's org, and the new agent\ncarries its whole lineage.",
		Fields: map[string]string{
			"agentView.avatar":                 "Avatar is an image the agent is drawn as — a link to one, or the bytes\ninline as a data URL, up to 96 KiB. Emoji is the one glyph a caller picked\nwhen they had no image. At most one is ever set; neither means the agent is\ndrawn as its initial, the same way a person with no photo is. Both are\niam/pkg/schema's Mark, so a face means the same thing on an agent as it\ndoes on a person or an org.\nAvatar is the agent's picture: an image URL, or the image itself inline as a\ndata URL up to 96 KiB. Empty when the agent has no image.",
			"agentView.avatar_licence":         "AvatarLicence is the short name of the licence the avatar image is used\nunder (\"Public domain\", \"CC0\"). Present only with an avatar image.",
			"agentView.avatar_source":          "AvatarSource is the page the avatar image is described on, where its author\nand licence can be read (a Wikimedia Commons file page, say). Present only\nwith an avatar image.",
			"agentView.cap_micro_usd":          "CapMicroUSD is the total this agent may spend within one Period, as an\ninteger number of micro-USD (1,000,000 = $1). It is required at creation: a\ncap of zero would mean no limit and no per-agent spend record at all.",
			"agentView.computeRef":             "ComputeRef is the visor machine this bot is bound to, opaque here: this\npackage stores and echoes it, and the binding's lifecycle belongs elsewhere.\nEmpty means unbound, which is what every one-shot agent is.",
			"agentView.consumed_micro_usd":     "ConsumedMicroUSD is what has been spent in the current period, in micro-USD.\nIt is settled from what the gateway reported, not from the quote.",
			"agentView.createdAt":              "CreatedAt is when the agent was defined, RFC 3339 in UTC to the second.",
			"agentView.description":            "Description is the one line another agent reads when deciding whether to call\nthis one: the tool catalogue publishes it as the description of `agent_<name>`,\nfalling back to \"agent <name>\" when it is empty. It is not part of the prompt —\nInstructions is — so writing the behaviour here reaches the caller and not the\nmodel.",
			"agentView.emoji":                  "Emoji is the single glyph a caller picked when they had no image. At most one\nof avatar and emoji is ever set; neither means the agent is drawn as its\ninitial, the same way a person with no photo is.",
			"agentView.executionMode":          "ExecutionMode is one-shot or long-running, and it decides who may start this\nagent. one-shot runs only when something POSTs to it; long-running is\nadditionally invoked by the scheduler on Schedule, once a minute against the\ncron. An org's long-running agents are capped, so a switch INTO it can be\nrefused with 409.",
			"agentView.groupId":                "GroupID names the Bot Group (\"grp_...\") this bot belongs to when assigned to\na group; empty when unassigned.",
			"agentView.id":                     "ID is the agent's stable handle, minted here as \"agent_\" + 32 hex characters\nof crypto/rand. A caller cannot choose it, and it never changes — unlike Name,\nwhich is the other way to address the same agent.",
			"agentView.isPrimary":              "IsPrimary is true for the org's single Primary Bot (at most one per org,\ndefault \"hanzo\") that directs subordinate bots and multi-layer Bot Groups.",
			"agentView.layer":                  "Layer is the bot's tier in the coordination hierarchy: 0 for the Primary Bot,\n1 for top-level group leads, and 2+ for nested worker and consensus bots.",
			"agentView.lineage":                "Lineage is every agent above this one, nearest first — the parent, its\nparent, and so on to the agent a person defined. All of them are in this\norg, so the principal this agent answers to is theirs.",
			"agentView.max_task_micro_usd":     "MaxTaskMicroUSD is the ceiling for a single run, in micro-USD. A session\ncannot exceed it even when the period cap still has room, so one runaway\ntask cannot consume a month.",
			"agentView.model":                  "Model is the Zen model this agent runs on, and it is always OUR name for it:\nwrites normalize through aimodel.ZenModel and the read normalizes again, so an\nupstream family name never leaves here even from a row written before that\nrule existed. A create that named none took the deployment's configured\ndefault, so this is where a caller learns which model it actually got.",
			"agentView.name":                   "Name is the agent's org-unique handle, matching\n^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$. It addresses the agent everywhere ID does,\nit is what a run row records, and it is the suffix of the `agent_<name>` tool\nother agents call this one by. Set once at create; no update route moves it,\nbecause moving it would orphan that history.",
			"agentView.parent":                 "Parent is the agent that spawned this one; absent for an agent a person\ndefined.",
			"agentView.period":                 "Period is the window the cap resets on: day, week or month.",
			"agentView.runs":                   "Runs is how many executions the org has recorded against this agent, counted\nat read time. The list and update reads count the WHOLE history; the detail\nread reports the size of the RecentRuns page it carries, which stops at 20 —\nso a detail row saying 20 means \"at least 20\", not \"exactly 20\".",
			"agentView.schedule":               "Schedule is the 5-field cron the scheduler fires a long-running agent on,\nevaluated once a minute. Required for long-running and DROPPED for one-shot —\na one-shot agent's schedule is not stored, so absence here is the mode's\nanswer rather than a value nobody set.",
			"agentView.serviceAccountId":       "ServiceAccountID is the IAM agent service account (<org>-<agent>) a scheduled\nrun is billed AS. It is what makes an autonomous run attributable to a\nprincipal rather than only to the org; empty means the org itself wears the\nspend.",
			"agentView.status":                 "Status is the agent's readiness: \"ready\", or \"retired\" for a built-in whose\nmember has left Hanzo's team. A retired agent is left out of the list and\nstill answers a get by its handle. Server-set; no route accepts it.",
			"agentView.tools":                  "Tools are the tool names this agent may call, and the list IS the authority:\nan agent that declares none gets none. The single entry \"*\" means whatever the\nfleet's MCP server serves at the moment of the run, resolved per run rather\nthan frozen here, which is how the default assistant reaches subsystems that\nshipped after it was defined. Empty array, never null.",
			"agentView.updatedAt":              "UpdatedAt is the last time any field above was written, same format. It moves\non an update to the DEFINITION and never on a run, so a busy agent nobody has\nedited keeps an old one.",
			"createAgentIn.avatar":             "Avatar and Emoji are how the agent APPEARS. An image wins when both are\ngiven — it is the thing somebody made — and both empty leaves the agent\ndrawn as its initial. Validated by iam/pkg/schema, the same rule a person's\navatar passes, so the 96 KiB bound and the accepted URL forms are stated\nonce for every subject that has a face.",
			"createAgentIn.avatar_licence":     "AvatarLicence is the licence's short name, one line of up to 128 characters\n(\"Public domain\"). Like avatar_source, it is not stored without an avatar.",
			"createAgentIn.avatar_source":      "AvatarSource is the https page the avatar image is described on, up to 2048\ncharacters. It belongs to the image: without an avatar it is not stored.",
			"createAgentIn.cap_micro_usd":      "The budget, required. An agent is not creatable without one: a zero cap\nwould mean no limit and no record of its spend, which is what a budget\nexists to remove. Integer micro-USD; the CLI converts dollars before sending.",
			"createAgentIn.computeRef":         "ComputeRef optionally binds this bot to a visor machine. Opaque here, bounded\nat 256 characters, and not resolved — this package stores the reference and\nthe binding's lifecycle belongs elsewhere.",
			"createAgentIn.description":        "Description is the one line published as the description of the `agent_<name>`\ntool, which is how another agent decides whether to call this one. Optional,\nand worth writing for exactly that reason.",
			"createAgentIn.emoji":              "Emoji is the single glyph shown when there is no image. An image WINS when\nboth are given — it is the thing somebody made — and both empty leaves the\nagent drawn as its initial.",
			"createAgentIn.executionMode":      "ExecutionMode is one-shot or long-running. Empty takes one-shot, which runs\nonly when something POSTs to it. long-running additionally requires Schedule,\nand counts against a per-org cap that answers 409 when it is full.",
			"createAgentIn.groupId":            "GroupID optionally assigns this bot to an existing Bot Group (by grp_... id\nor group name) at creation time.",
			"createAgentIn.instructions":       "Instructions is the system prompt, up to 32 KiB, stored verbatim. This is what\nthe model reads; Description is what other CALLERS read.",
			"createAgentIn.isPrimary":          "IsPrimary promotes this newly created bot to the org's sole Primary Bot\n(Layer 0), atomically clearing isPrimary on any previous Primary Bot in the\norg.",
			"createAgentIn.layer":              "Layer sets the bot's coordination tier (0 for Primary Bot, 1+ for subordinate\nlayers).",
			"createAgentIn.max_task_micro_usd": "MaxTaskMicroUSD is the ceiling for a single run, in micro-USD. A session\ncannot exceed it even when the period cap still has room, so one runaway\ntask cannot consume a month.",
			"createAgentIn.model":              "Model names the model to run on. Omit it to take the deployment's configured\ndefault; name one and it is checked against the gateway's served catalogue\nhere, so a model this deployment cannot serve is refused now rather than at\nthe first run. Stored under our own name for it, whatever spelling arrives.",
			"createAgentIn.name":               "Name is the agent's org-unique handle and the only required field. It must\nmatch ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$, and a name already taken in this org\nis a 409 rather than an overwrite. It is permanent: no update route moves it.",
			"createAgentIn.parent":             "Parent is the agent spawning this one — its id or name, in the caller's\norg. The new agent answers to the org its parent answers to, and a parent\noutside the caller's org is not found: an agent is never spawned into a\nprincipal its creator does not answer to. Omitted for an agent a person\ndefines. Set once; no update moves it.",
			"createAgentIn.period":             "Period is the window the cap resets on: day, week or month.",
			"createAgentIn.schedule":           "Schedule is the 5-field cron a long-running agent fires on, parsed here so a\nbad expression is a 400 and not an agent that silently never runs. Required\nwith long-running; DISCARDED for one-shot rather than stored unused.",
			"createAgentIn.serviceAccountId":   "ServiceAccountID optionally names the IAM agent service account (<org>-<agent>)\na scheduled run should be billed AS, so an autonomous run is attributable to a\nprincipal rather than only to the org. Same 256-character bound, also\nunresolved here.",
			"createAgentIn.tools":              "Tools are the tool names this agent may call. Omitted or empty grants NONE —\nthat default is the agent's authority and is not widened anywhere. The single\nentry \"*\" means whatever the fleet's MCP server serves at the time of each run.",
		},
		Example: json.RawMessage(`{"name":"helper","model":"enso-flash","instructions":"be terse"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/:ref/run", zip.Doc{
		Description: "Executes the agent: it composes the agent's instructions with the caller\ninput and runs a real chat completion via the in-process AI client, then\nrecords the run. Every returned run reflects an execution that actually\nhappened — an inference failure is recorded and returned as an error run, not\nhidden and not fabricated.",
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/a2a", zip.Doc{
		Description: "Answers one JSON-RPC request.",
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/bootstrap", zip.Doc{
		Description: "Ensures the caller's org has its single Primary Bot\n(default name \"hanzo\", Layer 0, full cloud & computer-use tools) and returns\nit. Calling bootstrap repeatedly is idempotent: once an org has a Primary Bot,\nthat bot is returned unchanged without creating a second primary.",
		Fields: map[string]string{
			"agentView.avatar":             "Avatar is an image the agent is drawn as — a link to one, or the bytes\ninline as a data URL, up to 96 KiB. Emoji is the one glyph a caller picked\nwhen they had no image. At most one is ever set; neither means the agent is\ndrawn as its initial, the same way a person with no photo is. Both are\niam/pkg/schema's Mark, so a face means the same thing on an agent as it\ndoes on a person or an org.\nAvatar is the agent's picture: an image URL, or the image itself inline as a\ndata URL up to 96 KiB. Empty when the agent has no image.",
			"agentView.avatar_licence":     "AvatarLicence is the short name of the licence the avatar image is used\nunder (\"Public domain\", \"CC0\"). Present only with an avatar image.",
			"agentView.avatar_source":      "AvatarSource is the page the avatar image is described on, where its author\nand licence can be read (a Wikimedia Commons file page, say). Present only\nwith an avatar image.",
			"agentView.cap_micro_usd":      "CapMicroUSD is the total this agent may spend within one Period, as an\ninteger number of micro-USD (1,000,000 = $1). It is required at creation: a\ncap of zero would mean no limit and no per-agent spend record at all.",
			"agentView.computeRef":         "ComputeRef is the visor machine this bot is bound to, opaque here: this\npackage stores and echoes it, and the binding's lifecycle belongs elsewhere.\nEmpty means unbound, which is what every one-shot agent is.",
			"agentView.consumed_micro_usd": "ConsumedMicroUSD is what has been spent in the current period, in micro-USD.\nIt is settled from what the gateway reported, not from the quote.",
			"agentView.createdAt":          "CreatedAt is when the agent was defined, RFC 3339 in UTC to the second.",
			"agentView.description":        "Description is the one line another agent reads when deciding whether to call\nthis one: the tool catalogue publishes it as the description of `agent_<name>`,\nfalling back to \"agent <name>\" when it is empty. It is not part of the prompt —\nInstructions is — so writing the behaviour here reaches the caller and not the\nmodel.",
			"agentView.emoji":              "Emoji is the single glyph a caller picked when they had no image. At most one\nof avatar and emoji is ever set; neither means the agent is drawn as its\ninitial, the same way a person with no photo is.",
			"agentView.executionMode":      "ExecutionMode is one-shot or long-running, and it decides who may start this\nagent. one-shot runs only when something POSTs to it; long-running is\nadditionally invoked by the scheduler on Schedule, once a minute against the\ncron. An org's long-running agents are capped, so a switch INTO it can be\nrefused with 409.",
			"agentView.groupId":            "GroupID names the Bot Group (\"grp_...\") this bot belongs to when assigned to\na group; empty when unassigned.",
			"agentView.id":                 "ID is the agent's stable handle, minted here as \"agent_\" + 32 hex characters\nof crypto/rand. A caller cannot choose it, and it never changes — unlike Name,\nwhich is the other way to address the same agent.",
			"agentView.isPrimary":          "IsPrimary is true for the org's single Primary Bot (at most one per org,\ndefault \"hanzo\") that directs subordinate bots and multi-layer Bot Groups.",
			"agentView.layer":              "Layer is the bot's tier in the coordination hierarchy: 0 for the Primary Bot,\n1 for top-level group leads, and 2+ for nested worker and consensus bots.",
			"agentView.lineage":            "Lineage is every agent above this one, nearest first — the parent, its\nparent, and so on to the agent a person defined. All of them are in this\norg, so the principal this agent answers to is theirs.",
			"agentView.max_task_micro_usd": "MaxTaskMicroUSD is the ceiling for a single run, in micro-USD. A session\ncannot exceed it even when the period cap still has room, so one runaway\ntask cannot consume a month.",
			"agentView.model":              "Model is the Zen model this agent runs on, and it is always OUR name for it:\nwrites normalize through aimodel.ZenModel and the read normalizes again, so an\nupstream family name never leaves here even from a row written before that\nrule existed. A create that named none took the deployment's configured\ndefault, so this is where a caller learns which model it actually got.",
			"agentView.name":               "Name is the agent's org-unique handle, matching\n^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$. It addresses the agent everywhere ID does,\nit is what a run row records, and it is the suffix of the `agent_<name>` tool\nother agents call this one by. Set once at create; no update route moves it,\nbecause moving it would orphan that history.",
			"agentView.parent":             "Parent is the agent that spawned this one; absent for an agent a person\ndefined.",
			"agentView.period":             "Period is the window the cap resets on: day, week or month.",
			"agentView.runs":               "Runs is how many executions the org has recorded against this agent, counted\nat read time. The list and update reads count the WHOLE history; the detail\nread reports the size of the RecentRuns page it carries, which stops at 20 —\nso a detail row saying 20 means \"at least 20\", not \"exactly 20\".",
			"agentView.schedule":           "Schedule is the 5-field cron the scheduler fires a long-running agent on,\nevaluated once a minute. Required for long-running and DROPPED for one-shot —\na one-shot agent's schedule is not stored, so absence here is the mode's\nanswer rather than a value nobody set.",
			"agentView.serviceAccountId":   "ServiceAccountID is the IAM agent service account (<org>-<agent>) a scheduled\nrun is billed AS. It is what makes an autonomous run attributable to a\nprincipal rather than only to the org; empty means the org itself wears the\nspend.",
			"agentView.status":             "Status is the agent's readiness: \"ready\", or \"retired\" for a built-in whose\nmember has left Hanzo's team. A retired agent is left out of the list and\nstill answers a get by its handle. Server-set; no route accepts it.",
			"agentView.tools":              "Tools are the tool names this agent may call, and the list IS the authority:\nan agent that declares none gets none. The single entry \"*\" means whatever the\nfleet's MCP server serves at the moment of the run, resolved per run rather\nthan frozen here, which is how the default assistant reaches subsystems that\nshipped after it was defined. Empty array, never null.",
			"agentView.updatedAt":          "UpdatedAt is the last time any field above was written, same format. It moves\non an update to the DEFINITION and never on a run, so a busy agent nobody has\nedited keeps an old one.",
			"bootstrapPrimaryIn.model":     "Model optionally sets the Zen model when creating the Primary Bot; defaults\nto the deployment's chat model.",
			"bootstrapPrimaryIn.name":      "Name optionally overrides the Primary Bot's handle when creating or promoting\none; defaults to \"hanzo\".",
			"bootstrapPrimaryOut.agent":    "Agent is the org's active Primary Bot (at Layer 0, isPrimary = true).",
			"bootstrapPrimaryOut.created":  "Created is true when a new Primary Bot row was inserted by this call, and\nfalse when an existing bot was returned or promoted.",
		},
		Example: json.RawMessage(`{"name":"hanzo"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/briefs", zip.Doc{
		Description: "Assigns a research brief to a venture lead, dispatches durable\nchild tasks to the designated specialist agents, attributes each specialist's\ncited findings and unsupported-claim flags, and runs the lead synthesis once\nall specialist tasks complete. If any specialist fails, completed specialist\nwork is preserved on the brief (`partial_failure`) so `POST /v1/agent/briefs/:id/rerun`\nre-executes only the failed specialist task.",
		Fields: map[string]string{
			"BriefAttribution.agentId":      "AgentID is the contributing agent's stable ID.",
			"BriefAttribution.agentName":    "AgentName is the contributing agent's handle.",
			"BriefAttribution.citations":    "Citations are the source citations contributed by this agent.",
			"BriefAttribution.function":     "Function is the studio function represented by the agent.",
			"BriefAttribution.microUsd":     "MicroUSD is the spend attributed to this agent on the brief in integer micro-USD.",
			"BriefAttribution.parentId":     "ParentID is the manager agent ID this agent reports to.",
			"BriefAttribution.role":         "Role is \"lead\" or \"specialist\".",
			"BriefAttribution.runId":        "RunID is the agent_runs execution ID that produced this contribution.",
			"BriefAttribution.summary":      "Summary is a concise excerpt of what this agent produced.",
			"BriefRecord.attribution":       "Attribution records who did what across the lead and specialist agents.",
			"BriefRecord.citations":         "Citations are the deduplicated source citations across the specialist tasks and lead synthesis.",
			"BriefRecord.createdAt":         "CreatedAt is when the brief was submitted, as Unix seconds.",
			"BriefRecord.id":                "ID is the stable brief handle (`brief_...`).",
			"BriefRecord.leadAgent":         "LeadAgent is the venture lead agent's handle.",
			"BriefRecord.leadAgentId":       "LeadAgentID is the venture lead agent's stable ID.",
			"BriefRecord.leadRunId":         "LeadRunID is the recorded run ID of the lead synthesis once completed.",
			"BriefRecord.openQuestions":     "OpenQuestions are the unresolved questions surfaced for domain review or follow-up.",
			"BriefRecord.question":          "Question is the nonconfidential research question assigned to the venture lead.",
			"BriefRecord.rerunsPerformed":   "RerunsPerformed is how many failed specialist tasks were re-executed on the latest rerun.",
			"BriefRecord.skippedCompleted":  "SkippedCompleted is how many already-completed specialist tasks were preserved without re-running on the latest rerun.",
			"BriefRecord.status":            "Status is the brief's lifecycle state: completed or partial_failure.",
			"BriefRecord.synthesis":         "Synthesis is the lead agent's integrated synthesis once all specialist child tasks succeed.",
			"BriefRecord.tasks":             "Tasks are the durable specialist child tasks belonging to this brief.",
			"BriefRecord.title":             "Title is the short headline of the research brief.",
			"BriefRecord.totalMicroUsd":     "TotalMicroUSD is the total spend across all specialist tasks and the lead synthesis in integer micro-USD.",
			"BriefRecord.unsupportedClaims": "UnsupportedClaims are the claims flagged as lacking primary empirical support.",
			"BriefRecord.updatedAt":         "UpdatedAt is when the brief was last updated, as Unix seconds.",
			"BriefRecord.venture":           "Venture is the venture slug this research brief belongs to.",
			"BriefTask.agentId":             "AgentID is the specialist agent's stable handle (`agent_...`).",
			"BriefTask.agentName":           "AgentName is the specialist agent's name in the organization.",
			"BriefTask.attempts":            "Attempts counts how many times this specialist task has been executed.",
			"BriefTask.briefId":             "BriefID is the parent research brief identifier (`brief_...`).",
			"BriefTask.citations":           "Citations are the source references extracted from the specialist's output.",
			"BriefTask.error":               "Error records the failure reason when status is \"error\".",
			"BriefTask.function":            "Function is the studio function the specialist represents.",
			"BriefTask.id":                  "ID is the stable task identifier (`task_...`).",
			"BriefTask.lineage":             "Lineage is the specialist's ancestor agent IDs, nearest first.",
			"BriefTask.microUsd":            "MicroUSD is the cumulative spend of this child task in integer micro-USD.",
			"BriefTask.output":              "Output is the attributable text produced by the specialist when status is \"done\".",
			"BriefTask.parentId":            "ParentID is the manager agent ID in the specialist's lineage.",
			"BriefTask.prompt":              "Prompt is the specialist-scoped sub-brief dispatched to this agent.",
			"BriefTask.runId":               "RunID is the recorded agent_runs row ID for the latest execution attempt.",
			"BriefTask.status":              "Status is the durable task state: pending, done, or error.",
			"BriefTask.unsupportedClaims":   "UnsupportedClaims are the claims the specialist flagged as lacking primary evidence.",
			"BriefTask.updatedAt":           "UpdatedAt is when the child task was last updated, as Unix seconds.",
			"submitBriefIn.failOnce":        "FailOnce optionally names specialist handles whose initial task execution should fail before model invocation, used to exercise and verify selective child-task retry.",
			"submitBriefIn.lead":            "Lead is the venture lead agent handle or ID; defaults to \"venture-lead\".",
			"submitBriefIn.question":        "Question is the research question or brief handed to the venture lead.",
			"submitBriefIn.specialists":     "Specialists lists the specialist agent handles or IDs to dispatch durable child tasks to; defaults to regulatory-clinical and market-competitive when omitted.",
			"submitBriefIn.title":           "Title is the headline of the research brief.",
			"submitBriefIn.venture":         "Venture is the venture slug this brief belongs to.",
		},
	})
