	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/groups", zip.Doc{
		Description: "Defines a multi-bot coordination group at a hierarchy layer\nunder Primary Bot \"hanzo\" (or nested under a parent group) with a leader, Lux\nQuasar consensus, or voting policy.",
		Fields: map[string]string{
			"createGroupIn.description":     "Description explains what work this group handles for parent coordinators.",
			"createGroupIn.layer":           "Layer places the group in the coordination hierarchy (defaults to 1, or\nparent.Layer + 1 when parentGroupId is set).",
			"createGroupIn.members":         "Members lists the org's bot names or ids to assign to this group.",
			"createGroupIn.name":            "Name is the group's org-unique handle matching ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$.",
			"createGroupIn.parentGroupId":   "ParentGroupID optionally nests this group beneath an existing parent group\n(by id or name).",
			"createGroupIn.policy":          "Policy configures how the group coordinates (defaults to quasar aurora when\nomitted).",
			"groupPolicy.alpha":             "Alpha is the supermajority quorum fraction in (0, 1] required for a round to\nlock on a candidate proposal (defaults to 0.67, i.e. 2/3, for quasar).",
			"groupPolicy.beta":              "Beta is the number of consecutive quorum rounds required to finalize a Lux\nQuasar certificate (defaults to 2).",
			"groupPolicy.confidenceFloor":   "ConfidenceFloor is the minimum self-reported confidence in [0, 1] required by\nthe kai policy before accepting a consensus answer without escalation.",
			"groupPolicy.customRule":        "CustomRule holds the natural-language adjudication rubric applied when kind\nis custom.",
			"groupPolicy.escalateToPrimary": "EscalateToPrimary forwards deadlocked or low-confidence ballots to the org's\nPrimary Bot (\"hanzo\") for tie-breaking finality.",
			"groupPolicy.kind":              "Kind selects the coordination mechanism: leader, quasar, majority, weighted,\nunanimous, kai, or custom.",
			"groupPolicy.leader":            "Leader names the bot that decomposes tasks and synthesizes member outputs\nwhen kind is leader (or adjudicates when kind is custom).",
			"groupPolicy.maxBudgetMicroUSD": "MaxBudgetMicroUSD caps the combined spend of a single group run in integer\nmicro-USD when positive.",
			"groupPolicy.quasarProfile":     "QuasarProfile selects a Lux Quasar preset (polaris, aurora, or pulsar) when\nkind is quasar. Explicit sampleK, alpha, and beta values override the preset.",
			"groupPolicy.sampleK":           "SampleK caps how many group members are sampled per consensus round (for\nexample 3 for polaris, 5 for aurora, 7 for pulsar). Zero samples all members.",
			"groupPolicy.weights":           "Weights optionally overrides per-member voting weights for weighted and\nquasar policies; unlisted members default to weight 1.0.",
			"groupView.createdAt":           "CreatedAt is when the group was created, RFC 3339 UTC.",
			"groupView.description":         "Description summarizes what the group owns so Primary Bot \"hanzo\" and parent\nlayers know when to delegate to it.",
			"groupView.id":                  "ID is the group's stable server-minted handle (\"grp_\" + hex).",
			"groupView.layer":               "Layer is the hierarchy tier (1 = direct report to Primary Bot \"hanzo\", 2+ =\nnested sub-groups and specialist pools).",
			"groupView.members":             "Members lists the bot names belonging to this group in deterministic order.",
			"groupView.name":                "Name is the group's org-unique handle, addressable as group_<name> in tools\nand transport routing.",
			"groupView.parentGroupId":       "ParentGroupID names the parent Bot Group (\"grp_...\") when this group sits at\nLayer 2 or deeper; empty means it reports directly to Primary Bot \"hanzo\".",
			"groupView.policy":              "Policy defines the leader, Lux Quasar, or voting consensus rules for this\ngroup.",
			"groupView.updatedAt":           "UpdatedAt is when the group definition was last updated, RFC 3339 UTC.",
			"groupWeight.agent":             "Agent is the member bot's org-unique name or public agent_... id.",
			"groupWeight.weight":            "Weight is the non-negative voting multiplier assigned to this member (1.0 is\nstandard parity).",
		},
		Example: json.RawMessage(`{"name":"core-eng","layer":1,"policy":{"kind":"quasar","quasarProfile":"aurora"}}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/groups/:ref/run", zip.Doc{
		Description: "Executes a prompt across a Bot Group using its configured\ncoordination policy (leader delegation, Lux Quasar consensus with SHA3-384\ncSHAKE256 finality certificates, majority, weighted, unanimous, kai, or\ncustom) and returns the finalized response along with every member's vote.",
		Fields: map[string]string{
			"groupVoteView.agent":             "Agent is the member bot's org-unique name.",
			"groupVoteView.choice":            "Choice is the zero-based candidate index this member attested to in the final\nballot round.",
			"groupVoteView.confidence":        "Confidence is the member's self-reported certainty in [0, 1].",
			"groupVoteView.model":             "Model is the Zen model that served this member's turn.",
			"groupVoteView.proposal":          "Proposal is the candidate answer produced by this member bot.",
			"groupVoteView.runId":             "RunID is the recorded run_... handle of this member's execution.",
			"groupVoteView.status":            "Status is \"ok\" when the member answered or \"error\" when its turn failed.",
			"groupVoteView.weight":            "Weight is the effective voting weight applied to this member's ballot.",
			"quasarCertView.alpha":            "Alpha is the quorum threshold fraction required per round.",
			"quasarCertView.beta":             "Beta is the number of consecutive quorum rounds required for finality.",
			"quasarCertView.checkpointDigest": "CheckpointDigest is the 48-byte hex SHA3-384 cSHAKE256 commitment under\ndomain LUX-QUASAR-CHECKPOINT-V1 binding the threshold digest to the winning\noutput.",
			"quasarCertView.escalated":        "Escalated is true when Primary Bot \"hanzo\" broke a tie after unfinalized\nrounds.",
			"quasarCertView.finalized":        "Finalized is true when the winning proposal held >= alpha support for beta\nconsecutive rounds.",
			"quasarCertView.profile":          "Profile names the active Lux Quasar profile (polaris, aurora, or pulsar).",
			"quasarCertView.rounds":           "Rounds is the total number of ballot rounds executed.",
			"quasarCertView.sampleK":          "SampleK is the validator sample size used per round.",
			"quasarCertView.support":          "Support is the winning proposal's weighted vote share in [0, 1] on the final\nround.",
			"quasarCertView.thresholdDigest":  "ThresholdDigest is the 48-byte hex SHA3-384 cSHAKE256 commitment under domain\nLUX-QUASAR-GROUPED-THRESHOLD-V1 over the round ballot tally.",
			"runGroupIn.input":                "Input is the task or prompt submitted to the Bot Group, up to 128 KiB.",
			"runGroupIn.ref":                  "Ref is the group's public grp_... id or org-unique name from the path.",
			"runGroupOut.durationMs":          "DurationMs is the wall-clock duration of the coordinated execution in\nmilliseconds.",
			"runGroupOut.error":               "Error describes what failed when status is \"error\".",
			"runGroupOut.group":               "Group is the org-unique name of the Bot Group.",
			"runGroupOut.groupId":             "GroupID is the grp_... handle of the Bot Group that executed the task.",
			"runGroupOut.id":                  "ID is the unique grp_run_... identifier for this coordinated execution.",
			"runGroupOut.layer":               "Layer is the hierarchy tier at which the group executed.",
			"runGroupOut.output":              "Output is the synthesized, consensus-finalized, or leader-approved response.",
			"runGroupOut.policy":              "Policy is the coordination policy kind used for this execution.",
			"runGroupOut.quasar":              "Quasar carries the Lux Quasar finality certificate when policy is quasar.",
			"runGroupOut.status":              "Status is \"ok\" when the group produced an answer or \"error\" when every member\nfailed.",
			"runGroupOut.votes":               "Votes lists each participating member bot's run, proposal, and ballot choice.",
		},
		Example: json.RawMessage(`{"ref":"core-eng","input":"Audit the auth service rollout plan"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/proposals/:id/decide", zip.Doc{
		Description: "Approves or rejects a proposed role candidate. Approving a\nproposal creates the specialist agent under its reporting line once (and is\nidempotent on repeated approval); rejecting records the rejection without\ncreating an agent.",
		Fields: map[string]string{
			"RoleProposal.agentId":            "AgentID is the created agent's handle (`agent_...`) once the proposal has been approved; empty when pending or rejected.",
			"RoleProposal.cap_micro_usd":      "CapMicroUSD is the period budget cap in integer micro-USD that will be set on the created agent.",
			"RoleProposal.createdAt":          "CreatedAt is when the proposal was generated, as Unix seconds.",
			"RoleProposal.decidedAt":          "DecidedAt is when the proposal was approved or rejected, as Unix seconds.",
			"RoleProposal.decidedBy":          "DecidedBy records the subject who approved or rejected the proposal.",
			"RoleProposal.decisionReason":     "DecisionReason records the operator's note when approving or rejecting.",
			"RoleProposal.estimatedMicroUsd":  "EstimatedMicroUSD is the estimated monthly spend for this role in integer micro-USD.",
			"RoleProposal.examples":           "Examples are the concrete failed runs, unsupported claims, or review bottlenecks backing the proposal.",
			"RoleProposal.function":           "Function is the studio function this role candidate belongs to.",
			"RoleProposal.id":                 "ID is the stable proposal identifier (`prop_...`).",
			"RoleProposal.instructions":       "Instructions is the system prompt that will govern the proposed role.",
			"RoleProposal.max_task_micro_usd": "MaxTaskMicroUSD is the single-run budget ceiling in integer micro-USD that will be set on the created agent.",
			"RoleProposal.name":               "Name is the org-unique agent handle that will be created if the proposal is approved.",
			"RoleProposal.period":             "Period is the budget reset window: day, week, or month.",
			"RoleProposal.rationale":          "Rationale explains why the nightly review proposed this role candidate.",
			"RoleProposal.reportingLine":      "ReportingLine is the manager agent handle (`parent`) the proposed role reports to.",
			"RoleProposal.status":             "Status is the proposal's decision state: pending, approved, or rejected.",
			"RoleProposal.title":              "Title is the human-readable title of the proposed role.",
			"RoleProposal.tools":              "Tools are the MCP tool names the proposed role will be granted.",
			"RoleProposal.venture":            "Venture is the venture slug the role candidate is proposed for.",
			"decideProposalIn.decision":       "Decision is the operator's verdict: \"approve\" (creates the agent role once) or \"reject\" (records rejection without creating an agent).",
			"decideProposalIn.id":             "ID is the proposal handle (`prop_...`) from the URL path.",
			"decideProposalIn.reason":         "Reason is an optional operator note explaining the approval or rejection.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/proposals/review", zip.Doc{
		Description: "Runs the scheduled review of repeated failures, missing\nexpertise, and human review effort across the organization's runs, briefs,\nand observed coverage gaps, producing role candidate proposals with concrete\nexamples, a micro-USD cost estimate, and a reporting line.",
		Fields: map[string]string{
			"RoleGapInput.estimatedMicroUsd":     "EstimatedMicroUSD is the estimated period cost for the proposed role in integer micro-USD.",
			"RoleGapInput.examples":              "Examples lists concrete run IDs, unsupported claims, or reviewer corrections demonstrating the gap.",
			"RoleGapInput.failureCount":          "FailureCount is how many repeated failures were observed in this area.",
			"RoleGapInput.function":              "Function is the studio function where the coverage gap or failure occurred (e.g. \"regulatory-clinical\").",
			"RoleGapInput.reportingLine":         "ReportingLine names the manager agent handle the proposed role will report to; defaults to \"venture-lead\".",
			"RoleGapInput.reviewSeconds":         "ReviewSeconds is the human domain-review effort recorded on this gap in seconds.",
			"RoleGapInput.roleName":              "RoleName is the suggested agent handle for the proposed specialist role; generated from Function and Topic when omitted.",
			"RoleGapInput.title":                 "Title is the human-readable title for the proposed role.",
			"RoleGapInput.topic":                 "Topic describes the missing expertise or recurring failure domain (e.g. \"laboratory-lims-telemetry-integration\").",
			"RoleProposal.agentId":               "AgentID is the created agent's handle (`agent_...`) once the proposal has been approved; empty when pending or rejected.",
			"RoleProposal.cap_micro_usd":         "CapMicroUSD is the period budget cap in integer micro-USD that will be set on the created agent.",
			"RoleProposal.createdAt":             "CreatedAt is when the proposal was generated, as Unix seconds.",
			"RoleProposal.decidedAt":             "DecidedAt is when the proposal was approved or rejected, as Unix seconds.",
			"RoleProposal.decidedBy":             "DecidedBy records the subject who approved or rejected the proposal.",
			"RoleProposal.decisionReason":        "DecisionReason records the operator's note when approving or rejecting.",
			"RoleProposal.estimatedMicroUsd":     "EstimatedMicroUSD is the estimated monthly spend for this role in integer micro-USD.",
			"RoleProposal.examples":              "Examples are the concrete failed runs, unsupported claims, or review bottlenecks backing the proposal.",
			"RoleProposal.function":              "Function is the studio function this role candidate belongs to.",
			"RoleProposal.id":                    "ID is the stable proposal identifier (`prop_...`).",
			"RoleProposal.instructions":          "Instructions is the system prompt that will govern the proposed role.",
			"RoleProposal.max_task_micro_usd":    "MaxTaskMicroUSD is the single-run budget ceiling in integer micro-USD that will be set on the created agent.",
			"RoleProposal.name":                  "Name is the org-unique agent handle that will be created if the proposal is approved.",
			"RoleProposal.period":                "Period is the budget reset window: day, week, or month.",
			"RoleProposal.rationale":             "Rationale explains why the nightly review proposed this role candidate.",
			"RoleProposal.reportingLine":         "ReportingLine is the manager agent handle (`parent`) the proposed role reports to.",
			"RoleProposal.status":                "Status is the proposal's decision state: pending, approved, or rejected.",
			"RoleProposal.title":                 "Title is the human-readable title of the proposed role.",
			"RoleProposal.tools":                 "Tools are the MCP tool names the proposed role will be granted.",
			"RoleProposal.venture":               "Venture is the venture slug the role candidate is proposed for.",
			"reviewProposalsIn.failureThreshold": "FailureThreshold is the minimum number of failed runs on an agent or function that triggers a role proposal; defaults to 2.",
			"reviewProposalsIn.observedGaps":     "ObservedGaps are explicit coverage gaps, unsupported-claim clusters, or review-effort spikes to evaluate alongside stored run history.",
			"reviewProposalsIn.venture":          "Venture optionally scopes the nightly review to a specific venture slug.",
			"reviewProposalsOut.created":         "Created is how many new role proposals were generated during this review pass.",
			"reviewProposalsOut.proposals":       "Proposals are the active role candidate proposals resulting from the review.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/roster", zip.Doc{
		Description: "Turns an approved organization chart into agent definitions in the\ncaller's organization, resolving manager reporting lines (`parent` and\n`lineage`) and shared role templates with explicit versions. Applying the same\nroster again (or resuming an interrupted launch) updates existing roles in\nplace without duplicating agents or budgets.",
		Fields: map[string]string{
			"RoleSpec.cap_micro_usd":         "CapMicroUSD is the period budget cap in integer micro-USD; defaults to the template's cap when omitted.",
			"RoleSpec.duties":                "Duties is the system prompt (instructions) governing the role's behavior and output.",
			"RoleSpec.executionMode":         "ExecutionMode is \"one-shot\" (default) or \"long-running\".",
			"RoleSpec.expertise":             "Expertise is the catalog description explaining the role's domain expertise.",
			"RoleSpec.function":              "Function names the studio function (\"lead\" or one of the seven studio functions).",
			"RoleSpec.manager":               "Manager names the parent agent handle or id this role reports to in the org chart.",
			"RoleSpec.max_task_micro_usd":    "MaxTaskMicroUSD is the per-run budget ceiling in integer micro-USD; defaults to the template's ceiling when omitted.",
			"RoleSpec.model":                 "Model optionally overrides the model this role runs on.",
			"RoleSpec.name":                  "Name is the agent handle to create or update in the organization (e.g. \"venture-lead\" or \"specialist-regulatory-clinical\").",
			"RoleSpec.output":                "Output describes the required deliverable format for this role.",
			"RoleSpec.period":                "Period is the budget reset window (day, week, or month); defaults to \"month\".",
			"RoleSpec.schedule":              "Schedule is the 5-field cron expression when executionMode is \"long-running\".",
			"RoleSpec.sources":               "Sources lists the knowledge and evidence sources this role is permitted to query.",
			"RoleSpec.templateId":            "TemplateID optionally selects a shared RoleTemplate by id to inherit defaults from.",
			"RoleSpec.templateVersion":       "TemplateVersion records the explicit shared template version used for this role; defaults to StudioTemplateVersion.",
			"RoleSpec.tools":                 "Tools lists the MCP tool names this role is allowed to call.",
			"agentView.avatar":               "Avatar is an image the agent is drawn as — a link to one, or the bytes\ninline as a data URL, up to 96 KiB. Emoji is the one glyph a caller picked\nwhen they had no image. At most one is ever set; neither means the agent is\ndrawn as its initial, the same way a person with no photo is. Both are\niam/pkg/schema's Mark, so a face means the same thing on an agent as it\ndoes on a person or an org.\nAvatar is the agent's picture: an image URL, or the image itself inline as a\ndata URL up to 96 KiB. Empty when the agent has no image.",
			"agentView.avatar_licence":       "AvatarLicence is the short name of the licence the avatar image is used\nunder (\"Public domain\", \"CC0\"). Present only with an avatar image.",
			"agentView.avatar_source":        "AvatarSource is the page the avatar image is described on, where its author\nand licence can be read (a Wikimedia Commons file page, say). Present only\nwith an avatar image.",
			"agentView.cap_micro_usd":        "CapMicroUSD is the total this agent may spend within one Period, as an\ninteger number of micro-USD (1,000,000 = $1). It is required at creation: a\ncap of zero would mean no limit and no per-agent spend record at all.",
			"agentView.computeRef":           "ComputeRef is the visor machine this bot is bound to, opaque here: this\npackage stores and echoes it, and the binding's lifecycle belongs elsewhere.\nEmpty means unbound, which is what every one-shot agent is.",
			"agentView.consumed_micro_usd":   "ConsumedMicroUSD is what has been spent in the current period, in micro-USD.\nIt is settled from what the gateway reported, not from the quote.",
			"agentView.createdAt":            "CreatedAt is when the agent was defined, RFC 3339 in UTC to the second.",
			"agentView.description":          "Description is the one line another agent reads when deciding whether to call\nthis one: the tool catalogue publishes it as the description of `agent_<name>`,\nfalling back to \"agent <name>\" when it is empty. It is not part of the prompt —\nInstructions is — so writing the behaviour here reaches the caller and not the\nmodel.",
			"agentView.emoji":                "Emoji is the single glyph a caller picked when they had no image. At most one\nof avatar and emoji is ever set; neither means the agent is drawn as its\ninitial, the same way a person with no photo is.",
			"agentView.executionMode":        "ExecutionMode is one-shot or long-running, and it decides who may start this\nagent. one-shot runs only when something POSTs to it; long-running is\nadditionally invoked by the scheduler on Schedule, once a minute against the\ncron. An org's long-running agents are capped, so a switch INTO it can be\nrefused with 409.",
			"agentView.groupId":              "GroupID names the Bot Group (\"grp_...\") this bot belongs to when assigned to\na group; empty when unassigned.",
			"agentView.id":                   "ID is the agent's stable handle, minted here as \"agent_\" + 32 hex characters\nof crypto/rand. A caller cannot choose it, and it never changes — unlike Name,\nwhich is the other way to address the same agent.",
			"agentView.isPrimary":            "IsPrimary is true for the org's single Primary Bot (at most one per org,\ndefault \"hanzo\") that directs subordinate bots and multi-layer Bot Groups.",
			"agentView.layer":                "Layer is the bot's tier in the coordination hierarchy: 0 for the Primary Bot,\n1 for top-level group leads, and 2+ for nested worker and consensus bots.",
			"agentView.lineage":              "Lineage is every agent above this one, nearest first — the parent, its\nparent, and so on to the agent a person defined. All of them are in this\norg, so the principal this agent answers to is theirs.",
			"agentView.max_task_micro_usd":   "MaxTaskMicroUSD is the ceiling for a single run, in micro-USD. A session\ncannot exceed it even when the period cap still has room, so one runaway\ntask cannot consume a month.",
			"agentView.model":                "Model is the Zen model this agent runs on, and it is always OUR name for it:\nwrites normalize through aimodel.ZenModel and the read normalizes again, so an\nupstream family name never leaves here even from a row written before that\nrule existed. A create that named none took the deployment's configured\ndefault, so this is where a caller learns which model it actually got.",
			"agentView.name":                 "Name is the agent's org-unique handle, matching\n^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$. It addresses the agent everywhere ID does,\nit is what a run row records, and it is the suffix of the `agent_<name>` tool\nother agents call this one by. Set once at create; no update route moves it,\nbecause moving it would orphan that history.",
			"agentView.parent":               "Parent is the agent that spawned this one; absent for an agent a person\ndefined.",
			"agentView.period":               "Period is the window the cap resets on: day, week or month.",
			"agentView.runs":                 "Runs is how many executions the org has recorded against this agent, counted\nat read time. The list and update reads count the WHOLE history; the detail\nread reports the size of the RecentRuns page it carries, which stops at 20 —\nso a detail row saying 20 means \"at least 20\", not \"exactly 20\".",
			"agentView.schedule":             "Schedule is the 5-field cron the scheduler fires a long-running agent on,\nevaluated once a minute. Required for long-running and DROPPED for one-shot —\na one-shot agent's schedule is not stored, so absence here is the mode's\nanswer rather than a value nobody set.",
			"agentView.serviceAccountId":     "ServiceAccountID is the IAM agent service account (<org>-<agent>) a scheduled\nrun is billed AS. It is what makes an autonomous run attributable to a\nprincipal rather than only to the org; empty means the org itself wears the\nspend.",
			"agentView.status":               "Status is the agent's readiness: \"ready\", or \"retired\" for a built-in whose\nmember has left Hanzo's team. A retired agent is left out of the list and\nstill answers a get by its handle. Server-set; no route accepts it.",
			"agentView.tools":                "Tools are the tool names this agent may call, and the list IS the authority:\nan agent that declares none gets none. The single entry \"*\" means whatever the\nfleet's MCP server serves at the moment of the run, resolved per run rather\nthan frozen here, which is how the default assistant reaches subsystems that\nshipped after it was defined. Empty array, never null.",
			"agentView.updatedAt":            "UpdatedAt is the last time any field above was written, same format. It moves\non an update to the DEFINITION and never on a run, so a busy agent nobody has\nedited keeps an old one.",
			"applyRosterIn.roles":            "Roles are the explicit role definitions to create or update in topological manager order.",
			"applyRosterIn.seedDefaultSeven": "SeedDefaultSeven, when true, seeds the default venture-lead and all seven studio function specialists before applying any custom roles in Roles.",
			"applyRosterIn.templateVersion":  "TemplateVersion is the shared role template version to stamp on enrolled roles; defaults to StudioTemplateVersion.",
			"applyRosterIn.venture":          "Venture is the venture slug this roster belongs to, used for attribution and metadata.",
			"applyRosterOut.agents":          "Agents are the enrolled agent views in the organization after applying the roster.",
			"applyRosterOut.created":         "Created is how many new agent roles were created by this call.",
			"applyRosterOut.templateVersion": "TemplateVersion is the shared template version applied.",
			"applyRosterOut.updated":         "Updated is how many existing agent roles were updated idempotently in place without duplicating agents or budgets.",
			"applyRosterOut.venture":         "Venture is the venture slug the roster was applied for.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/sessions", zip.Doc{
		Description: "Opens a live agent session in the caller's org — the row every\nsurface (the CLI's outer agent, hanzo.bot, the console, chat) hangs its\nactivity off. A session with a parentSessionId becomes a subagent of that\nsession and inherits its root, so one flow is one tree; without one it is\nitself a root. Registering with a terminal status records a session that has\nalready finished.",
		Fields: map[string]string{
			"lastEventView.actor":          "Actor is who produced the turn, defaulted to the calling principal when the\nwriter named nobody.",
			"lastEventView.at":             "At is when the turn was recorded, RFC 3339 in UTC to the second.",
			"lastEventView.kind":           "Kind is what the turn was, from the log's closed six: message, tool-call,\nspawn, log, status, control.",
			"lastEventView.preview":        "Preview is the first 240 bytes of the event's payload, cut without regard for\nthe JSON inside it — it is a string to SHOW, never a value to parse. Read the\ndetail or the stream for the whole payload.",
			"lastEventView.seq":            "Seq is that event's position in the session's log — monotonic from 1, per\nsession. A reader holding it can ask the detail or stream reads for\neverything after it, so this doubles as the list's resume cursor.",
			"registerReq.account":          "Account is which subscription or API account under that provider served the\nrun, up to 256 characters. It is what lets a revoke of that login stop exactly\nthe sessions it was paying for.",
			"registerReq.agent":            "Agent is the label the surface opening this session calls itself by\n(\"hanzo-dev\"). REQUIRED, up to 128 characters, and free text — nothing\nresolves it against a defined agent.",
			"registerReq.budget_micro_usd": "BudgetMicroUSD caps what this session may spend, integer micro-USD. Zero\nmeans no cap; a cap can be raised or removed later, never added.",
			"registerReq.channel":          "Channel is the collaborative channel this run was started in (HIP-0523), so a\nspace view can list the sessions of one channel. It is PROVENANCE and is set\nonly here: there is deliberately no way to move a session to another channel, so\nit is absent from the patch input and from UpdateSession's SET list.",
			"registerReq.cwd":              "Cwd is the directory the session starts in, up to 1024 characters. It can be\nmoved later, because a linked shell walks around.",
			"registerReq.host":             "Execution context — where this session runs (all optional).",
			"registerReq.parentSessionId":  "ParentSessionID makes this a subagent of that session: it inherits the\nparent's root, so one flow stays one tree. The parent must exist IN THE SAME\nORG — a foreign or unknown id is a 400, never a tree across tenants. Empty\nopens a root session.",
			"registerReq.project":          "The readable build (provenance.go): which product this session builds, and\nwhether its story may be read by the world.",
			"registerReq.provider":         "Account tag — the linked AI account this session ran under (login manager).",
			"registerReq.published":        "Published opens this session's story to the public build route. It is refused\nwithout a Project, because that route is keyed on (org, project) — a build\nwith no product is not a story anyone can open. False keeps it org-only.",
			"registerReq.repo":             "Repo is the code being worked on, up to 512 characters. A label the surface\nstates; nothing resolves it against the forge.",
			"registerReq.status":           "Status opens the session in one of running, paused, done or error. Empty means\nrunning. A TERMINAL status here (done, error) records a session that has\nalready finished — its end time is stamped now — and nothing can move it\nafterwards.",
			"registerReq.target":           "Target names a run-target the org has registered. Unlike Host and Repo it IS\nresolved: a target that does not exist in this org is a 400, so a session can\nnever claim to run on another tenant's machine. Empty names no machine.",
			"registerReq.taskRunId":        "TaskRunID is that workflow's particular run, same bound. Recorded, not\nresolved: this surface does not check the workflow exists.",
			"registerReq.taskWorkflowId":   "TaskWorkflowID links this session to the hanzoai/tasks workflow that executes\nit, up to 256 characters. Set it and control commands are forwarded to that\nengine; leave it and the running surface polls for them instead.",
			"registerReq.terminal":         "Terminal is the URL this session's live terminal is published at, so the\nconsole can watch it. Optional — a session that publishes nothing is still\na session.",
			"registerReq.title":            "Title is the human line a card shows, up to 512 characters. Optional, and\nchangeable later.",
			"sessionPark.message":          "Message is the run's own sentence for it, as its thread's card says it.",
			"sessionPark.reason":           "Reason is \"limit\" (the model API refused the run's calls for a usage limit),\n\"payment\" (its payer refused them), \"fault\" (the model API failed them after\nthe harness tried them again, and the run is tried again by itself) or \"restart\"\n(the pod driving the run was replaced, and it goes on at once on the next).",
			"sessionPark.resumeAt":         "ResumeAt is when the run is tried again by itself, RFC 3339 in UTC, as the\nauthority that set the limit states it. Absent when nothing names a time: the\nrun then goes on when credits are added, a plan or a cap changes, or a person\ncontinues it.",
			"sessionProgress.activity":     "Activity is the one line saying what the run is doing right now (\"running\nthe reaper's tests\"), up to 120 characters, in the model's words. Empty\nwhen nothing has estimated it yet.",
			"sessionProgress.at":           "At is when this was determined, RFC 3339 in UTC to the second. Read it as\nthe estimate's AGE: an estimate is not refreshed while nothing has\nhappened, and a stale one beside a run that is still moving is itself worth\nseeing. Empty when nothing has estimated it yet.",
			"sessionProgress.estimated":    "Estimated says a MODEL produced this, from the run's transcript, and it may\nbe wrong. False means the session's own row said it: a finished run is 100%\nbecause it finished, not because anything guessed. Never treat a true here\nas a measurement — it is the reason to look, not the answer.",
			"sessionProgress.pct":          "Pct is how much of the run is done, 0 to 100. THE KEY IS ABSENT when\nprogress is indeterminate — a run nobody can estimate is not a run that has\ndone nothing, and rendering the second for the first is the mistake this\nomission exists to make impossible. Read `phase` before reaching for it.",
			"sessionProgress.phase":        "Phase is what shape the run is in: queued, running, blocked, done, error, or\nunknown when nothing has estimated it yet. blocked means the transcript\nshows the run waiting on something — an approval, a credential, an answer —\nwhich is the one state the running surface cannot report about itself.\nerror only ever comes from the session's own terminal status. queued is the\nrun's own word that it is accepted and waiting for a place to start.",
			"sessionView.account":          "Account is which subscription or API account under that provider served it.\nTogether with Provider it is what a login revoke matches on to stop the\nsessions a withdrawn account was paying for.",
			"sessionView.actor":            "Actor is WHO this session belongs to, as \"org/sub\" — the same identity a run\nis billed under. A register that names none takes the calling principal. It is\nwhat scopes a login revoke, so a session with the wrong actor is a session the\nright person cannot stop.",
			"sessionView.agent":            "Agent is the label the surface running this session calls itself by\n(\"hanzo-dev\"), up to 128 characters. Required at register. It is free text,\nnot a reference: it need not name a defined agent, and nothing resolves it.",
			"sessionView.base":             "Base is the branch the run started from. Empty when it took the\nrepository's default and did not say which.",
			"sessionView.branch":           "Branch is the branch the run pushes its work to, and the only one it may\nwrite.",
			"sessionView.channel":          "Channel is the collaborative channel this run was started in (HIP-0523), empty\nwhen it came from anywhere else — a CLI, a schedule, an API call. It is what\nlets a space view show the runs of one channel beside its messages.",
			"sessionView.children":         "Children is the DIRECT fan-out — how many sessions name this one as parent —\nand not the size of the subtree. Read the tree for that.",
			"sessionView.createdAt":        "CreatedAt is when the row was written, same format. Every path that opens a\nsession stamps it and StartedAt from one clock reading, so the two are equal\non every session this surface has ever produced.",
			"sessionView.cwd":              "Cwd is the directory the session is working in NOW, not the one it started in:\na linked shell moves around, and a card showing where `hanzo link` was run\nanswers \"which work is this\" with something that was true once.",
			"sessionView.endedAt":          "EndedAt is when its run stopped, same format: it reached done, error or stopped,\nor it paused. Empty while it runs; a resume clears it, since it runs again.",
			"sessionView.environment":      "Environment is where the run executes: \"sandbox\" for a Hanzo sandbox, or the\nid of the org's machine it was routed to (the same id Target carries).",
			"sessionView.error":            "Error explains why the session ended in error, when it did. Empty for any other status.",
			"sessionView.events":           "Events is how many turns the session's log holds, counted at read time. It is\nthe whole log, however few of them RecentEvents carries.",
			"sessionView.host":             "Execution context (mission-control): the machine/repo/cwd a card shows and\nthe run-target a session is dispatched to. Omitted when a surface didn't report it.",
			"sessionView.id":               "ID is the session's handle, minted here as \"sess_\" + 32 hex characters. Every\nlater read, patch, event append and control command is addressed with it, and\na caller cannot choose it.",
			"sessionView.kind":             "Kind is what sort of run this session is the view of — \"coding\" for a coding\nrun. Empty for a session no run tagged.",
			"sessionView.lastEvent":        "LastEvent is the compact latest-activity line for the list projection (nil in\nregister/patch/tree responses; set by list + detail). It lets a swipe card show\na live one-line preview without fetching full detail.",
			"sessionView.mode":             "Mode is what the run may do to its repository: \"build\" edits, commits and\npushes its branch; \"plan\" reads and answers with a plan, writing nothing.\nEmpty for a session no run tagged.",
			"sessionView.org":              "Org is the caller's OWN tenant, echoed so a client can build the public\nbuild URL (/builds/:org/:project) without a second call or a guess. It is\nnever another tenant's — every read is org-scoped before it gets here.",
			"sessionView.parentSessionId":  "ParentSessionID is the session that spawned this one, making this a subagent\nof it. Empty means this session is a root — a flow of its own. A parent always\nbelongs to the same org, so a tree never crosses a tenant.",
			"sessionView.park":             "Park is present while a coding run waits to go on by itself: the model API\nrefused it for a usage limit, or its payer refused it. The session is paused,\nholds no sandbox, and its work is on its branch. Absent for every other session.",
			"sessionView.pr":               "PR is the address of the pull request the run proposed. Empty until it\nproposes one, and for a run that changed nothing.",
			"sessionView.progress":         "Progress is how far along this run is — a share of its goal, a phase, and a\nline saying what it is doing. Always present, so a board never branches on\nwhether it is there; `phase` says \"unknown\" when nothing has estimated it.\nIt is a MODEL ESTIMATE wherever `estimated` is true, and the row's own word\nwhere it is false. See progress.go.",
			"sessionView.project":          "The readable build: the product this session built and whether its story\nis public (provenance.go).",
			"sessionView.provider":         "Provider is the linked AI account's provider (claude | codex | hanzo | …) that\nserved this run. Empty when the surface did not say.",
			"sessionView.published":        "Published is the author's decision to let anyone read this session's story at\nthe public build route. It only ever widens READ access to a session that\nalready exists and grants nothing else; false, an unpublished session is\ninvisible there no matter who asks. It cannot be true without a Project,\nbecause that route is keyed on (org, project).",
			"sessionView.repo":             "Repo is the code the session is working on, as the surface reported it. It is\ntruth the SURFACE states, so it is a label rather than something resolved here.",
			"sessionView.rootSessionId":    "RootSessionID is the top of this session's tree, inherited from the parent and\nshared by every node in one flow. A root session's own id, when it has no\nparent. It is the key one indexed read pulls a whole flow by, and what ?root=\nnarrows a list or a stream to.",
			"sessionView.sandbox":          "Sandbox is the id of the sandbox the run works in (\"m_\" and 24 hex), the\nhandle its terminal and its screen are opened with\n(/v1/sandbox/{id}/terminal, /screen). Set when the run leases it, and kept\nonce the run gives it back, when the id opens nothing. Empty for a run that\nnever leased one — a routed run, or a turn that only talked.",
			"sessionView.startedAt":        "StartedAt is when the session opened, RFC 3339 in UTC to the second.",
			"sessionView.status":           "Status is one of exactly four: running, paused, done, error. running and\npaused are LIVE; done and error are TERMINAL and monotonic — once a session\nreaches one it can never go back, because reopening a finished run would\nfabricate liveness. A control command never moves it: the surface running the\nagent reports the new status, and until it does the command is only recorded.",
			"sessionView.target":           "Target is the registered run-target this session is dispatched to — a machine\nthe org claimed, resolved same-org when it was set, so it can never point at\nanother tenant's computer. Empty means the session names no machine.",
			"sessionView.taskRunId":        "TaskRunID is that workflow's particular run. A workflow is the definition and\na run is one execution of it, which is why both are carried.",
			"sessionView.taskWorkflowId":   "TaskWorkflowID is the hanzoai/tasks durable workflow that actually EXECUTES\nthis session — this registry is the view, control and stream layer over it.\nSet, a control command is FORWARDED to that engine; empty, the running surface\npolls for commands instead, which is every session today.",
			"sessionView.terminal":         "Terminal is where this session can be WATCHED — the URL the machine\npublished for its live terminal. Omitted when it publishes none.",
			"sessionView.title":            "Title is the human line a card shows (\"ship the landing page\"), up to 512\ncharacters. Free text, and the one field a surface may rewrite as the work\nturns out to be something else.",
			"sessionView.updatedAt":        "UpdatedAt is the session's last-activity clock, same format. It moves on a\nwrite to the row — a status, a title, a re-dispatch — AND on every appended\nturn, because the append bumps it in the same transaction. The list is ordered\non CreatedAt, so this is the field that says whether a session is still saying\nanything.",
		},
		Example: json.RawMessage(`{"agent":"hanzo-dev","title":"ship the landing page","host":"gpu-01"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/sessions/:id/answer", zip.Doc{
		Description: "Answers a question a session's run asked its person — a coding\nrun's harness, or a turn of the app's conversation asking whether a coding run\nmay start — from the page the session is read on. The run waiting on it goes on\nwith the answer. Only the person the question is for may answer, once: a\nquestion already answered or closed answers 409, and one this session did not\nask answers 404.",
		Fields: map[string]string{
			"answerIn.chosen":     "Chosen says Text is one of the options the question offered.",
			"answerIn.id":         "ID is the session whose run asked, from the path.",
			"answerIn.question":   "Question is the question answered, as the session's `asked` status names it.",
			"answerIn.text":       "Text is the answer: a pressed option's label, or the person's own words.",
			"answerView.question": "Question is the question answered.",
			"answerView.text":     "Text is what it was answered with.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/sessions/:id/budget", zip.Doc{
		Description: "Sets, raises, or removes a session's cap.\n\n  - a replacement must be strictly greater than what the session has consumed\n  - removal is one-way: a session whose cap was removed cannot take one again,\n    and a session created without one cannot be given one\n  - raising or removing the cap resumes work that paused at it",
		Fields: map[string]string{
			"sessionBudgetIn.budget_micro_usd":     "BudgetMicroUSD is the new cap, or null to remove the cap for good.",
			"sessionBudgetIn.id":                   "ID is the session, from the path.",
			"sessionBudgetView.budget_micro_usd":   "BudgetMicroUSD is this session's own ceiling in micro-USD, beyond the agent's.\nA replacement must strictly exceed what the session has already consumed, and\nremoving it is one-way.",
			"sessionBudgetView.budget_removed":     "BudgetRemoved says the session's own cap was taken off. It cannot be put back.",
			"sessionBudgetView.consumed_micro_usd": "ConsumedMicroUSD is what has been spent in the current period, in micro-USD.\nIt is settled from what the gateway reported, not from the quote.",
			"sessionBudgetView.id":                 "ID names the session.",
			"sessionBudgetView.status":             "Status is the session's state: running, paused at its cap, or done.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/sessions/:id/events", zip.Doc{
		Description: "Records one turn of a session's transcript and answers 201 with it.\n\nA `progress` turn additionally MOVES THE SESSION'S PROGRESS, marked as the run's\nown word rather than an estimate, and pushes the updated session onto the live\nstream — so a board's bar follows the run without polling and without a second\nwrite path. See progress.go.\n\nTHE TURN IS SCANNED BEFORE IT IS STORED. The same engine the code-security\nsurface runs reads the payload at this boundary, and a credential in it refuses\nthe append with 422 rather than redacting it — a redacted transcript is one\nthat still had the secret in it once, and this way the author learns which\nvalue to rotate. The refusal carries every finding: the rule, the severity, the\nline, a MASKED preview and the fingerprint. The secret is never in the answer.\n\nA TURN THAT NAMES ITSELF IS STORED ONCE. With a `requestId`, a repeat of the\nappend (a client retrying after a 5xx or a timeout) answers 201 with the turn\nthe first request stored and changes nothing: no second turn, no second frame\non the stream, no second move of progress. The same id with another kind, actor\nor payload is another request under a reused id, refused 422.",
		Fields: map[string]string{
			"eventIn.actor":       "Actor is who produced the turn. Empty takes the validated caller, which is\nwhat an agent writing its own transcript wants; naming one is for a surface\nrecording on somebody else's behalf.",
			"eventIn.id":          "ID is the session to append to, from the path.",
			"eventIn.kind":        "Kind is what this turn IS: message, tool-call, spawn, log, status, control\nor progress. Anything else is refused — the vocabulary is closed so a\nreader can branch on it.",
			"eventIn.payload":     "Payload is the turn's own body, any valid JSON up to 64 KiB. It is SCANNED\nfor credentials before it is stored, and a hit refuses the whole append with\n422 and the findings — this plane never redacts a secret into a transcript\nit then keeps.\n\nIts SHAPE is the writer's business for every kind but one: a `progress`\nturn is the run reporting on itself in a shape this surface publishes —\n{\"pct\":0-100 (optional), \"phase\":\"queued|running|blocked|done\",\n\"activity\":\"≤120 chars\"} — so a malformed one is refused with 400 instead\nof being stored as prose nobody reads.",
			"eventIn.requestId":   "RequestID names this append so it can be made again safely: a second append\nto the same session with the same id stores nothing and answers with the\nturn the first one stored; the same id with another turn is refused 422. Up\nto 256 bytes, no control characters. Leave it out and every append is its own\nturn.",
			"eventView.actor":     "Actor is who produced the turn. A write that names nobody takes the calling\nprincipal, so this is rarely empty in practice.",
			"eventView.createdAt": "CreatedAt is when the turn was recorded, RFC 3339 in UTC to the second. Seconds\nare coarse enough that two turns can share one, which is why Seq and not this\nis the order.",
			"eventView.id":        "ID is the event's own handle, minted as \"evt_\" + 32 hex characters. It\nidentifies the turn; Seq is what ORDERS it.",
			"eventView.kind":      "Kind is what the turn IS, from a closed six: message (a model turn),\ntool-call, spawn (a subagent started), log, status, control (a steering\ncommand the running surface consumes). Anything else is refused at the write.",
			"eventView.payload":   "Payload is the turn's body, embedded as JSON rather than as a string —\nwhatever the writer sent, up to 64 KiB, checked for well-formedness and\nscanned for credentials before it was stored. Its SHAPE is the writer's\nbusiness and varies by Kind; this surface does not interpret it, except\nthat every string in it is kept as plain text: terminal escape sequences\nand control characters other than the line break and the tab are removed.",
			"eventView.seq":       "Seq is the turn's position in this session's log: monotonic from 1, assigned\nby the store inside the insert, and unique PER SESSION rather than globally.\nIt is the cursor a reader resumes from after a reconnect — ask for everything\nafter your last-seen seq.",
			"eventView.sessionId": "SessionID is the session this turn belongs to. Carried on every event so a\nstream frame stands alone — a subscriber watching a whole tree gets turns from\nseveral sessions down one connection.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/agents POST /v1/agent/sessions/:id/message", zip.Doc{
		Description: "Sends a steering message to a running session — the endpoint a\nhuman or another agent interrupts through. It requires a `message` or a\n`payload`; the other three commands do not.\n\nA chat turn's run READS it: the message is handed to the model as the person's\nnext words at its next step, and a message that arrives while the model is\nwriting its answer gets a step of its own before the answer stands. A turn that\nhas already answered takes no more and answers 409 — what is said after an\nanswer is a new turn.",
		Fields: map[string]string{
			"controlIn.id":            "ID is the session to steer, from the path.",
			"controlIn.message":       "Message is free text for the running agent, up to 16 KiB, scanned for\ncredentials before it is stored like the payload. On a stop it is recorded\nas the cancellation reason.",
			"controlIn.payload":       "Payload is a structured argument for the command: any valid JSON up to\n64 KiB, scanned for credentials before it is stored (a hit refuses the\ncommand with 422 and the findings). A task-backed session receives it as\nthe forwarded signal's argument.",
			"controlResult.command":   "Command is the verb that was recorded: pause, resume, stop or message.",
			"controlResult.event":     "Event is the durable control event the command became. The intent is\nrecorded whether or not it reached an engine, which is what makes a\nstream-consuming surface able to act on it.",
			"controlResult.forwarded": "Forwarded is whether the command also reached the durable-execution engine.\nFALSE IS NOT A FAILURE: a session with no workflow link, or a deployment\nwith no tasks backend, is record-only by design. A forward that was\nattempted and failed is a 502, never a false here.",
			"controlResult.run":       "Run is the run a resume started, under the same session. Empty for every\nother command.",
			"eventView.actor":         "Actor is who produced the turn. A write that names nobody takes the calling\nprincipal, so this is rarely empty in practice.",
			"eventView.createdAt":     "CreatedAt is when the turn was recorded, RFC 3339 in UTC to the second. Seconds\nare coarse enough that two turns can share one, which is why Seq and not this\nis the order.",
			"eventView.id":            "ID is the event's own handle, minted as \"evt_\" + 32 hex characters. It\nidentifies the turn; Seq is what ORDERS it.",
			"eventView.kind":          "Kind is what the turn IS, from a closed six: message (a model turn),\ntool-call, spawn (a subagent started), log, status, control (a steering\ncommand the running surface consumes). Anything else is refused at the write.",
			"eventView.payload":       "Payload is the turn's body, embedded as JSON rather than as a string —\nwhatever the writer sent, up to 64 KiB, checked for well-formedness and\nscanned for credentials before it was stored. Its SHAPE is the writer's\nbusiness and varies by Kind; this surface does not interpret it, except\nthat every string in it is kept as plain text: terminal escape sequences\nand control characters other than the line break and the tab are removed.",
			"eventView.seq":           "Seq is the turn's position in this session's log: monotonic from 1, assigned\nby the store inside the insert, and unique PER SESSION rather than globally.\nIt is the cursor a reader resumes from after a reconnect — ask for everything\nafter your last-seen seq.",
			"eventView.sessionId":     "SessionID is the session this turn belongs to. Carried on every event so a\nstream frame stands alone — a subscriber watching a whole tree gets turns from\nseveral sessions down one connection.",
		},
	})
